/* Trust Navy Theme — Corporate, established */
:root {
    --theme-primary: #1e3a5f;
    --theme-primary-dark: #172e4d;
    --theme-primary-light: #e0f2fe;
    --theme-accent: #2563eb;
    --theme-bg: #ffffff;
    --theme-bg-alt: #f8fafc;
    --theme-text: #0f172a;
    --theme-text-secondary: #334155;
    --theme-text-muted: #64748b;
    --theme-border: #cbd5e1;
    --theme-shadow: rgba(30, 58, 95, 0.1);
    /* 图表/多色标签辅助色（chart-blue 用天蓝区别于主题的深海军蓝/accent蓝，避免撞色） */
    --theme-chart-blue: #0ea5e9;
    --theme-chart-green: #16a34a;
    --theme-chart-purple: #7c3aed;
    --theme-chart-yellow: #d97706;
}

body {
    background: var(--theme-bg);
    color: var(--theme-text);
}

.proposal-header {
    background: var(--theme-primary);
    color: white;
}

.proposal-header-accent {
    background: var(--theme-accent);
}

.proposal-section-title {
    color: var(--theme-primary);
    border-bottom: 3px solid var(--theme-primary);
    padding-bottom: 0.5rem;
}

.proposal-highlight {
    background: var(--theme-primary-light);
    border-left: 4px solid var(--theme-primary);
}

.proposal-cta {
    background: var(--theme-primary);
    color: white;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.proposal-cta:hover {
    background: var(--theme-primary-dark);
}

.proposal-cta-secondary {
    background: transparent;
    color: var(--theme-primary);
    border: 2px solid var(--theme-primary);
}

.proposal-price {
    color: var(--theme-primary);
    font-weight: 700;
}

.proposal-table {
    border: 2px solid var(--theme-border);
}

.proposal-table th {
    background: var(--theme-primary);
    color: white;
    text-transform: uppercase;
    font-size: 0.85em;
    letter-spacing: 0.05em;
}

.proposal-table tr:nth-child(even) {
    background: var(--theme-bg-alt);
}

.proposal-card {
    border: 1px solid var(--theme-border);
    box-shadow: 0 2px 4px var(--theme-shadow);
}

.proposal-card:hover {
    border-color: var(--theme-primary);
    box-shadow: 0 4px 12px var(--theme-shadow);
}

.proposal-footer {
    background: var(--theme-primary);
    color: white;
}

.proposal-footer a {
    color: var(--theme-primary-light);
}

/* Corporate seal/badge */
.proposal-seal {
    border: 3px solid var(--theme-primary);
    border-radius: 50%;
    padding: 1rem;
    color: var(--theme-primary);
}

